using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — strongly-typed metadata
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>() — check-without-throwing
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({info!.Type.Name})");

// Now demonstrate the "not available" path.
// A source-gen context that only knows about Person — not about int[].
var strict = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (strict.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrInfo))
    Console.WriteLine($"TryGetTypeInfo<int[]> → found ({arrInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<int[]> → not available (no exception thrown)");

// Positive check on the same strict context for a known type.
if (strict.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person> on strict context → found");

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
internal partial class SmallContext : JsonSerializerContext;

